mapper.select:
select f.follow_user_id userId,count(1) `match` from corgi_user_follow f left join corgi_user_detail d on d.user_id = f.follow_user_id
where f.is_deleted = '0'
and f.uptime >= #{date}
and d.role = '1'
and d.role != '1'
group by f.follow_user_id order by `match` desc limit #{limit}

mapper.update:
update corgi.corgi_billboard set user_id = #{toId}
where `date` = #{date}
and user_id = #{fromId}
